from __future__ import annotations

import json
import math
import sys
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
SOURCE = TASK_DIR / "source"
OUTPUT_DIR = TASK_DIR / "outputs"

if str(SOURCE) not in sys.path:
    sys.path.insert(0, str(SOURCE))

from desc.stability.terpsichore.benchmark import run_comparison  # noqa: E402


CASE_PATHS = {
    "physical": TASK_DIR / "fixtures" / "public_parity_case" / "case.json",
    "reduced": TASK_DIR / "fixtures" / "public_reduced_case" / "case.json",
    "anisotropic": TASK_DIR / "fixtures" / "public_anisotropic_case" / "case.json",
}


def _finite_number_count(value: object) -> int:
    if isinstance(value, bool):
        return 0
    if isinstance(value, (int, float)):
        return int(math.isfinite(float(value)))
    if isinstance(value, dict):
        return sum(_finite_number_count(item) for item in value.values())
    if isinstance(value, (list, tuple)):
        return sum(_finite_number_count(item) for item in value)
    return 0


def _public_case_view(report: dict[str, object]) -> dict[str, object]:
    target = report.get("target")
    baseline = report.get("baseline")
    target_representation = target.get("representation") if isinstance(target, dict) else None
    baseline_representation = (
        baseline.get("representation") if isinstance(baseline, dict) else None
    )
    return {
        "workflow_result_available": isinstance(target, dict)
        and isinstance(baseline, dict),
        "finite_observation_count": _finite_number_count(report),
        "configuration_effect_observed": (
            isinstance(target_representation, dict)
            and isinstance(baseline_representation, dict)
            and target_representation != baseline_representation
        ),
    }


def _write_report(payload: dict[str, object], exit_code: int) -> int:
    OUTPUT_DIR.mkdir(exist_ok=True)
    encoded = json.dumps(payload, indent=2, sort_keys=True, allow_nan=False) + "\n"
    (OUTPUT_DIR / "public_parity_report.json").write_text(encoded, encoding="utf-8")
    print(encoded, end="")
    return exit_code


def main() -> int:
    try:
        reports = {
            name: run_comparison(path) for name, path in CASE_PATHS.items()
        }
        cases = {name: _public_case_view(report) for name, report in reports.items()}
        completed = all(
            case["workflow_result_available"]
            and int(case["finite_observation_count"]) > 0
            and case["configuration_effect_observed"]
            for case in cases.values()
        )
    except Exception as exc:  # noqa: BLE001 - infrastructure has a distinct state.
        return _write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    return _write_report(
        {
            "schema_version": "1.0",
            "status": "workflow_completed" if completed else "pre_fix_expected_failure",
            "cases": cases,
            "case_count": len(cases),
        },
        0 if completed else 1,
    )


if __name__ == "__main__":
    raise SystemExit(main())

"""Perturbation-representation controls for TERPSICHORE-native calculations."""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np


@dataclass(frozen=True)
class TerpsichoreRepresentation:
    """Method-level controls associated with one perturbation convention."""

    parfac: float
    phase: float
    xi_basis: str
    eta_basis: str
    cospar: float
    cospr2: float


def resolve_representation(parfac: float) -> TerpsichoreRepresentation:
    """Resolve a supported TERPSICHORE perturbation representation.

    The migrated implementation historically exercised the baseline convention.
    This adapter is the boundary through which additional method-valid
    conventions enter the native coefficient and matrix path.
    """

    parfac = float(parfac)
    if not any(abs(parfac - allowed) < 1e-12 for allowed in (0.0, 0.5)):
        raise ValueError("parfac must be either 0.0 or 0.5.")
    phase = parfac * np.pi
    xi_basis, eta_basis = ("sin", "cos") if parfac < 0.25 else ("cos", "sin")
    return TerpsichoreRepresentation(
        parfac=parfac,
        phase=phase,
        xi_basis=xi_basis,
        eta_basis=eta_basis,
        cospar=1.0,
        cospr2=2.0,
    )
"""Configuration objects for the DESC-native TERPSICHORE migration."""

from dataclasses import dataclass, field


@dataclass(frozen=True)
class TerpsichoreVacuumOptions:
    """Vacuum pseudo-plasma mesh options matching TERPSICHORE concepts."""

    ivac: int = 0
    lmeshv: int = 1
    dsvac: float = 0.0
    pvac: float = 2.0
    qvac: float = 2.0

    def __post_init__(self):
        if self.ivac < 0:
            raise ValueError("ivac must be non-negative.")
        if self.ivac == 0 and self.dsvac != 0.0:
            raise ValueError("dsvac must be 0 when ivac is 0.")
        if self.ivac > 0 and self.dsvac <= 0.0:
            raise ValueError("dsvac must be positive when ivac > 0.")


@dataclass(frozen=True)
class TerpsichoreWallOptions:
    """Conducting wall options compatible with TERPSICHORE nomenclature."""

    nowall: int = -1
    awall: float = 2.0
    ewall: float = 1.0
    dwall: float = 0.0
    drwal: float = 0.0
    dzwal: float = 0.0
    gwall: float | None = None
    wct: float = 0.0

    def __post_init__(self):
        if self.awall <= 0:
            raise ValueError("awall must be positive.")
        if self.ewall <= 0:
            raise ValueError("ewall must be positive.")


@dataclass(frozen=True)
class TerpsichoreSolverOptions:
    """Eigen-solver options for TERPSICHORE-native stability analysis."""

    solver: str = "pamera"
    al0: float = -5e-1
    maxiter: int = 100
    tol: float = 1e-10

    def __post_init__(self):
        if self.solver not in {"pamera", "scipy"}:
            raise ValueError("solver must be 'pamera' or 'scipy'.")
        if self.maxiter <= 0:
            raise ValueError("maxiter must be positive.")
        if self.tol <= 0:
            raise ValueError("tol must be positive.")


@dataclass(frozen=True)
class TerpsichoreOptions:
    """Top-level options for a TERPSICHORE-native DESC run."""

    mode_family: int = -1
    surfs: int = 101
    M_max: int = 8
    N_min: int = -4
    N_max: int = 4
    parity: str = "cos"
    deltaJp: float = 1e-4
    modelk: int = 0
    vacuum: TerpsichoreVacuumOptions = field(default_factory=TerpsichoreVacuumOptions)
    wall: TerpsichoreWallOptions | None = None
    solver: TerpsichoreSolverOptions = field(default_factory=TerpsichoreSolverOptions)

    def __post_init__(self):
        if self.surfs < 2:
            raise ValueError("surfs must be at least 2.")
        if self.M_max < 0:
            raise ValueError("M_max must be non-negative.")
        if self.N_min > self.N_max:
            raise ValueError("N_min must be <= N_max.")
        if self.parity not in {"cos", "sin"}:
            raise ValueError("parity must be 'cos' or 'sin'.")
        if self.deltaJp <= 0:
            raise ValueError("deltaJp must be positive.")
        if self.modelk not in {0, 1, 2, 3}:
            raise ValueError("modelk must be one of 0, 1, 2, 3.")

"""Radial mesh objects for TERPSICHORE stability analysis."""

from dataclasses import dataclass

import numpy as np


@dataclass(frozen=True)
class TerpsichoreRadialGrid:
    """TERPSICHORE-style radial grid in normalized toroidal flux ``s``."""

    s_nodes: np.ndarray
    ni: int
    ivac: int = 0

    def __post_init__(self):
        s_nodes = np.asarray(self.s_nodes, dtype=float)
        if s_nodes.ndim != 1:
            raise ValueError("s_nodes must be one-dimensional.")
        if s_nodes.size != self.ni + self.ivac + 1:
            raise ValueError("s_nodes length must equal ni + ivac + 1.")
        if self.ni < 1:
            raise ValueError("ni must be positive.")
        if self.ivac < 0:
            raise ValueError("ivac must be non-negative.")
        if np.any(np.diff(s_nodes) <= 0):
            raise ValueError("s_nodes must be strictly increasing.")
        if not np.isclose(s_nodes[0], 0.0):
            raise ValueError("s_nodes must start at 0.")
        if not np.isclose(s_nodes[self.ni], 1.0):
            raise ValueError("plasma boundary s_nodes[ni] must be 1.")
        object.__setattr__(self, "s_nodes", s_nodes)

    @property
    def n_intervals(self):
        return self.ni + self.ivac

    @property
    def centers(self):
        return 0.5 * (self.s_nodes[1:] + self.s_nodes[:-1])

    @property
    def ds(self):
        return np.diff(self.s_nodes)

    @property
    def plasma_slice(self):
        return slice(0, self.ni)

    @property
    def vacuum_slice(self):
        return slice(self.ni, self.ni + self.ivac)

    def plasma_view(self):
        """Return a grid view containing only plasma intervals."""

        return type(self)(s_nodes=self.s_nodes[: self.ni + 1], ni=self.ni, ivac=0)

    @classmethod
    def uniform(cls, surfs=101, ivac=0, dsvac=0.0):
        """Create a uniform plasma mesh plus optional uniform vacuum mesh."""

        if surfs < 2:
            raise ValueError("surfs must be at least 2.")
        ni = surfs - 1
        plasma = np.linspace(0.0, 1.0, surfs)
        if ivac:
            vacuum = np.linspace(1.0, 1.0 + dsvac, ivac + 1)[1:]
            s_nodes = np.concatenate((plasma, vacuum))
        else:
            s_nodes = plasma
        return cls(s_nodes=s_nodes, ni=ni, ivac=ivac)
