from dataclasses import dataclass

import numpy as np


@dataclass(frozen=True)
class TerpsichorePotentialBlocks:
    """Potential-energy block matrices from TERPSICHORE ``LHSMAT``."""

    A: np.ndarray
    B: np.ndarray
    C: np.ndarray
    D: np.ndarray
    E: np.ndarray
    F: np.ndarray
    G: np.ndarray
    H: np.ndarray
    AI: np.ndarray
    BI: np.ndarray
    CC: np.ndarray
    DI: np.ndarray
    EI: np.ndarray
    FI: np.ndarray
    GI: np.ndarray
    HI: np.ndarray
    BL: np.ndarray
    BU: np.ndarray

    def __post_init__(self):
        shapes = {name: np.asarray(getattr(self, name)).shape for name in self.__dataclass_fields__}
        if len(set(shapes.values())) != 1:
            raise ValueError(f"all potential blocks must have the same shape, got {shapes}")


@dataclass(frozen=True)
class TerpsichoreKineticBlocks:
    """Kinetic-energy block matrices from TERPSICHORE ``RHSMAT``."""

    BA: np.ndarray
    BB: np.ndarray
    BC: np.ndarray
    BD: np.ndarray
    BE: np.ndarray
    BF: np.ndarray
    BG: np.ndarray
    BH: np.ndarray
    BBl: np.ndarray | None = None
    BBu: np.ndarray | None = None

    def __post_init__(self):
        base_names = ["BA", "BB", "BC", "BD", "BE", "BF", "BG", "BH"]
        shapes = {name: np.asarray(getattr(self, name)).shape for name in base_names}
        if len(set(shapes.values())) != 1:
            raise ValueError(f"all kinetic blocks must have the same shape, got {shapes}")
